10	func vuln(id, pkg, eco, class, installed, fixed string, sev scan.SeverityLevel) scan.Finding {
11		return scan.Finding{
12			ID: id, Source: scan.SourceTrivy, Severity: sev,
13			PkgName: pkg, Ecosystem: eco, Class: class, Version: installed, FixedIn: fixed,
14		}
15	}
