17	func TestSummarizeSplitsByClass(t *testing.T) {
18		findings := []scan.Finding{
19			vuln("CVE-1", "openssl", "alpine", scan.ClassOSPackages, "3.1.0", "3.1.4", scan.SeverityHigh),
20			vuln("CVE-2", "musl", "alpine", scan.ClassOSPackages, "1.2.3", "1.2.4", scan.SeverityLow),
21			vuln("CVE-3", "lodash", "npm", scan.ClassLangPackages, "4.0.0", "4.17.21", scan.SeverityCritical),
22			vuln("CVE-4", "old", "", "", "1.0.0", "1.0.1", scan.SeverityHigh),
23			vuln("CVE-5", "nofix", "npm", scan.ClassLangPackages, "1.0.0", "", scan.SeverityHigh),
24			{ID: "S1", Source: scan.SourceGitleaks},
25			{ID: "L1", Source: scan.SourceTrivyLicense, PkgName: "x", FixedIn: "9"},
26			{ID: "M1", Source: scan.SourceTrivyMisconfig},
27		}
28		got := Summarize(findings)
29		want := Summary{BaseImage: 2, Dependencies: 1, Unclassified: 1, Unfixed: 1}
30		if got != want {
31			t.Errorf("Summarize = %+v, want %+v", got, want)
32		}
33		if got.Fixable() != 4 {
34			t.Errorf("Fixable = %d, want 4", got.Fixable())
35		}
36	}
37	
38	func TestSummarizeOfNothing(t *testing.T) {
39		if got := Summarize(nil); got != (Summary{}) {
40			t.Errorf("Summarize(nil) = %+v, want zero", got)
41		}
42	}
43	
44	func TestGroupTakesTheHighestVersionAnyCVENeeds(t *testing.T) {
45		fixes := Group([]scan.Finding{
46			vuln("CVE-1", "golang.org/x/net", "gomod", scan.ClassLangPackages, "0.10.0", "0.17.0", scan.SeverityHigh),
47			vuln("CVE-2", "golang.org/x/net", "gomod", scan.ClassLangPackages, "0.10.0", "0.23.0", scan.SeverityCritical),
48			vuln("CVE-3", "golang.org/x/net", "gomod", scan.ClassLangPackages, "0.10.0", "0.17.0", scan.SeverityLow),
49		})
50		if len(fixes) != 1 {
51			t.Fatalf("got %d fixes, want 1", len(fixes))
52		}
53		fix := fixes[0]
54		if fix.Target != "0.23.0" {
55			t.Errorf("Target = %q, want the highest, 0.23.0", fix.Target)
56		}
57		if fix.Command != "go get golang.org/x/net@v0.23.0" {
58			t.Errorf("Command = %q", fix.Command)
59		}
60		if fix.Severity != scan.SeverityCritical {
61			t.Errorf("Severity = %q, want the worst", fix.Severity)
62		}
63		if want := []string{"CVE-1", "CVE-2", "CVE-3"}; !reflect.DeepEqual(fix.CVEs, want) {
64			t.Errorf("CVEs = %v, want %v", fix.CVEs, want)
65		}
66	}
67	
68	func TestGroupChoosesNothingWhenVersionsCannotBeOrdered(t *testing.T) {
69		fixes := Group([]scan.Finding{
70			vuln("CVE-1", "libfoo", "npm", scan.ClassLangPackages, "1.0.0", "1.0.1", scan.SeverityHigh),
71			vuln("CVE-2", "libfoo", "npm", scan.ClassLangPackages, "1.0.0", "weird", scan.SeverityHigh),
72		})
73		if fixes[0].Target != "" || fixes[0].Command != "" {
74			t.Errorf("unorderable versions produced Target %q / Command %q, want none", fixes[0].Target, fixes[0].Command)
75		}
76		if want := []string{"1.0.1", "weird"}; !reflect.DeepEqual(fixes[0].Options, want) {
77			t.Errorf("Options = %v, want %v", fixes[0].Options, want)
78		}
79	}
80	
81	// One CVE listing several fixed versions Trivy cannot rank is not resolved by
82	// guessing one of them.
83	func TestGroupKeepsAnAmbiguousFixedListVisible(t *testing.T) {
84		fixes := Group([]scan.Finding{
85			vuln("CVE-1", "libfoo", "npm", scan.ClassLangPackages, "1.0.0", "abc, def", scan.SeverityHigh),
86		})
87		if fixes[0].Target != "" {
88			t.Errorf("Target = %q, want none", fixes[0].Target)
89		}
90		if want := []string{"abc, def"}; !reflect.DeepEqual(fixes[0].Options, want) {
91			t.Errorf("Options = %v, want %v", fixes[0].Options, want)
92		}
93	}
94	
95	func TestGroupKeepsTwoInstalledVersionsApart(t *testing.T) {
96		fixes := Group([]scan.Finding{
97			vuln("CVE-1", "semver", "npm", scan.ClassLangPackages, "5.0.0", "5.7.2", scan.SeverityHigh),
98			vuln("CVE-1", "semver", "npm", scan.ClassLangPackages, "6.0.0", "6.3.1", scan.SeverityHigh),
99		})
100		if len(fixes) != 2 {
101			t.Fatalf("got %d fixes, want one per installed version", len(fixes))
102		}
103	}
104	
105	func TestGroupKeepsTwoEcosystemsApart(t *testing.T) {
106		fixes := Group([]scan.Finding{
107			vuln("CVE-1", "openssl", "alpine", scan.ClassOSPackages, "3.0.0", "3.0.1", scan.SeverityHigh),
108			vuln("CVE-2", "openssl", "pip", scan.ClassLangPackages, "3.0.0", "3.0.1", scan.SeverityHigh),
109		})
110		if len(fixes) != 2 {
111			t.Fatalf("got %d fixes, want 2", len(fixes))
112		}
113	}
114	
115	func TestGroupSortsWorstSeverityFirstAndSkipsWhatIsUnfixable(t *testing.T) {
116		fixes := Group([]scan.Finding{
117			vuln("CVE-1", "a", "npm", scan.ClassLangPackages, "1.0.0", "1.0.1", scan.SeverityLow),
118			vuln("CVE-2", "b", "npm", scan.ClassLangPackages, "1.0.0", "1.0.1", scan.SeverityCritical),
119			vuln("CVE-3", "c", "npm", scan.ClassLangPackages, "1.0.0", "", scan.SeverityCritical),
120			{ID: "S1", Source: scan.SourceGitleaks, PkgName: "d", FixedIn: "1"},
121		})
122		if len(fixes) != 2 {
123			t.Fatalf("got %d fixes, want 2 (unfixed and non-vulnerabilities skipped)", len(fixes))
124		}
125		if fixes[0].Package != "b" || fixes[1].Package != "a" {
126			t.Errorf("order = %s, %s; want b (critical) then a (low)", fixes[0].Package, fixes[1].Package)
127		}
128	}
129	
130	func TestGroupOfNothing(t *testing.T) {
131		if got := Group(nil); len(got) != 0 {
132			t.Errorf("Group(nil) = %v, want none", got)
133		}
134	}
